4     std::string GetFileContentHelper(const std::string &path)
5     {   
6         // 一份简单的读取二进制文件的代码​
7         std::ifstream in(path, std::ios::binary);
8         if (!in.is_open())
9             return ""; 
10         in.seekg(0, in.end);
11         int filesize = in.tellg();
12         in.seekg(0, in.beg);
13
14         std::string content;
15         content.resize(filesize);
16         in.read((char *)content.c_str(), filesize);
17
18         // std::vector<char> content(filesize);
19         // in.read(content.data(), filesize);
20
21         in.close();
22
23         return content;
24     } 
2. POST方法（重点）​
用途：用于传输实体的主体，通常用于提交表单数据。
示例： POST /submit.cgi HTTP/1.1
特性：可以发送大量的数据给服务器，并且数据包含在请求体中。
